# Owner(s): ["oncall: export"]
# [MODULE DOC] Tests that every ExportDB example case behaves as annotated. Supported cases
# must export in strict mode with the experimental new tracer and match eager outputs; not-
# supported-yet cases must raise; their rewrite variants must export successfully. Test
# methods are generated by parametrize over the example registry at import time.

import copy
import unittest

import torch._dynamo as torchdynamo
from torch._export import config
from torch._export.db.case import ExportCase, SupportLevel
from torch._export.db.examples import (
    filter_examples_by_support_level,
    get_rewrite_cases,
)
from torch.export import export
from torch.testing._internal.common_utils import (
    instantiate_parametrized_tests,
    IS_WINDOWS,
    parametrize,
    run_tests,
    TestCase,
)


@unittest.skipIf(IS_WINDOWS, "Windows not supported for this test")
@unittest.skipIf(not torchdynamo.is_dynamo_supported(), "dynamo doesn't support")
class ExampleTests(TestCase):
    # [CLASS DOC] Parametrized test case over ExportDB examples. Skipped on Windows and when
    # dynamo is unsupported. It holds no state besides a class attribute listing rewrite cases
    # that is computed in the class body from the not-supported examples; the rewrite test
    # method only exists if that list is non-empty.
    # TODO Maybe we should make this tests actually show up in a file?
    @parametrize(
        "name,case",
        filter_examples_by_support_level(SupportLevel.SUPPORTED).items(),
        name_fn=lambda name, case: f"case_{name}",
    )
    def test_exportdb_supported(self, name: str, case: ExportCase) -> None:
        # [FUNCTION DOC] Exports one supported ExportDB case in strict mode (new tracer
        # enabled via config patch, dynamic shapes from the case), prints the graph, and
        # asserts the exported module output equals the eager model output on deep-copied
        # example args and kwargs. If the case has extra args, also checks the exported module
        # against the model on them.
        model = case.model

        args_export = case.example_args
        kwargs_export = case.example_kwargs
        args_model = copy.deepcopy(args_export)
        kwargs_model = copy.deepcopy(kwargs_export)
        with config.patch(use_new_tracer_experimental=True):
            exported_program = export(
                model,
                case.example_args,
                case.example_kwargs,
                dynamic_shapes=case.dynamic_shapes,
                strict=True,
            )
        exported_program.graph_module.print_readable()

        self.assertEqual(
            exported_program.module()(*args_export, **kwargs_export),
            model(*args_model, **kwargs_model),
        )

        if case.extra_args is not None:
            args = case.extra_args
            args_model = copy.deepcopy(args)
            self.assertEqual(
                exported_program.module()(*args),
                model(*args_model),
            )

    @parametrize(
        "name,case",
        filter_examples_by_support_level(SupportLevel.NOT_SUPPORTED_YET).items(),
        name_fn=lambda name, case: f"case_{name}",
    )
    def test_exportdb_not_supported(self, name: str, case: ExportCase) -> None:
        # [FUNCTION DOC] Asserts that exporting a not-supported-yet case in strict mode with
        # the new tracer enabled raises one of: dynamo Unsupported, AssertionError, or
        # RuntimeError.
        model = case.model
        # pyre-ignore
        with self.assertRaises(
            (torchdynamo.exc.Unsupported, AssertionError, RuntimeError)
        ):
            with config.patch(use_new_tracer_experimental=True):
                _ = export(
                    model,
                    case.example_args,
                    case.example_kwargs,
                    dynamic_shapes=case.dynamic_shapes,
                    strict=True,
                )

    exportdb_not_supported_rewrite_cases = [
        (name, rewrite_case)
        for name, case in filter_examples_by_support_level(
            SupportLevel.NOT_SUPPORTED_YET
        ).items()
        for rewrite_case in get_rewrite_cases(case)
    ]
    if exportdb_not_supported_rewrite_cases:

        @parametrize(
            "name,rewrite_case",
            exportdb_not_supported_rewrite_cases,
            name_fn=lambda name, case: f"case_{name}_{case.name}",
        )
        def test_exportdb_not_supported_rewrite(
            self, name: str, rewrite_case: ExportCase
        ) -> None:
            # [FUNCTION DOC] Exports a rewritten (supported) variant of a not-supported case
            # in strict mode with its own dynamic shapes; passes if export does not raise. The
            # name argument is only used for the generated test id.
            # pyre-ignore
            export(
                rewrite_case.model,
                rewrite_case.example_args,
                rewrite_case.example_kwargs,
                dynamic_shapes=rewrite_case.dynamic_shapes,
                strict=True,
            )


instantiate_parametrized_tests(ExampleTests)


if __name__ == "__main__":
    run_tests()
